import React from "react";
import "./dashboard.css";

export default function AchievementsPanel({ me }) {
  // expects me.points (optional)
  const points = me?.points ?? 0;

  return (
    <div className="card achievements-card">
      <h4>Achievements</h4>
      <div className="points-large">
        <div className="points-number">{points}</div>
        <div className="points-sub">POINTS</div>
      </div>

      <div className="badges-area">
        <h5>Badges</h5>
        <div className="muted">No badges yet — participate to earn rewards.</div>
      </div>
    </div>
  );
}
